Gruesse("Lena");
Gruesse("Jonas");
Sterne(5);

void Gruesse(string name)
{
    Console.WriteLine($"Servus, {name}!");
}

void Sterne(int anzahl)
{
    for (int i = 0; i < anzahl; i++)
    {
        Console.Write("*");
    }
    Console.WriteLine();
}
// Ausgabe:
// Servus, Lena!
// Servus, Jonas!
// *****

int flaeche = Rechteck(4, 5);
Console.WriteLine(flaeche);                    // 20
Console.WriteLine(Rechteck(2, 3) + 10);        // 16
Console.WriteLine(Rechteck(Rechteck(1, 2), 3)); // 6

int Rechteck(int laenge, int breite)
{
    return laenge * breite;
}

for (int zahl = 1; zahl <= 6; zahl++)
{
    if (IstGerade(zahl))
    {
        Console.WriteLine($"{zahl} ist gerade");
    }
}
Console.WriteLine(Note(83));

bool IstGerade(int n)
{
    return n % 2 == 0;
}

string Note(int prozent)
{
    if (prozent >= 90) return "Sehr gut";
    if (prozent >= 80) return "Gut";
    if (prozent >= 65) return "Befriedigend";
    if (prozent >= 50) return "Genügend";
    return "Nicht genügend";   // für alle anderen Fälle
}
// Ausgabe:
// 2 ist gerade
// 4 ist gerade
// 6 ist gerade
// Gut

int[] klasse1 = { 12, 18, 7, 20 };
int[] klasse2 = { 15, 3 };

Console.WriteLine(Maximum(klasse1));   // 20
Console.WriteLine(Maximum(klasse2));   // 15

int Maximum(int[] zahlen)
{
    int max = zahlen[0];
    foreach (int z in zahlen)
    {
        if (z > max)
        {
            max = z;
        }
    }
    return max;
}

int punkte = 10;
Bonus(punkte);
Console.WriteLine(punkte);          // 10 – unverändert!

punkte = MitBonus(punkte);
Console.WriteLine(punkte);          // 15

void Bonus(int p)
{
    p = p + 5;   // ändert nur die Kopie
}

int MitBonus(int p)
{
    return p + 5;
}

